export const PET_NATIVE_PREVIEW_DEFAULTS: Readonly<Record<string,string>> = {"alpaca":"cream-alpaca","bear":"brown-bear","beaver":"north-american-beaver","bun":"porcelain","capybara":"capybara","cat":"white","cloud":"white","cow":"dairy-cow","chick":"yellow-chick","chinchilla":"gray-chinchilla","deer":"sika-deer","dog":"shiba-inu","duck":"mallard-duck","ferret":"sable-ferret","fox":"red-fox","goose":"greylag-goose","hamster":"syrian-hamster","hedgehog":"european-hedgehog","lion":"african-lion","monkey":"macaque","otter":"sea-otter","pig":"pink-pig","rabbit":"holland-lop","guinea-pig":"american-guinea-pig","owl":"barn-owl","parrot":"scarlet-macaw","penguin":"emperor-penguin","seal":"harbor-seal","sheep":"white-sheep","squirrel":"red-squirrel","sun":"solar","tiger":"bengal-tiger"}
const cache = new Map<string, AvatarDefinition>()
export function petNativePreviewDefinition(species: string, paletteId?: string): AvatarDefinition | undefined {
  const key = `${species}/${paletteId ?? PET_NATIVE_PREVIEW_DEFAULTS[species]}`
  const record = records[key]
  if (!record) return undefined
  const previous = cache.get(key)
  if (previous) return previous
  const definition = { ...common, scene: { ...common.scene, ...record } } as AvatarDefinition
  cache.set(key,definition)
  return definition
}
